{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/kanban-board.json
    Work items in lanes. Each lane has a title, a count and its cards; a card has a title, an optional tag and the person it belongs to. Axes: card (simple, detail: tag and person), cols (2, 3), tone, density. Moving a card between lanes is a port contract.
    Props (p): id, title, lanes, cards, countLabel, card, cols, tone, density, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_lanes = (p.lanes ?? null) -%}
{%- set v_cards = (p.cards ?? null) -%}
{%- set v_countLabel = (p.countLabel ?? null) -%}
{%- set v_card = (p.card ?? 'detail') -%}
{%- set v_cols = (p.cols ?? '3') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- set c_12 -%}
  {%- set c_11 -%}
    {%- for v_lane in ui_l(v_lanes) %}
      {%- set c_10 -%}
        {%- set c_3 -%}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_lane, ['title'])) }}
          {%- endset -%}
          {{ include('ui/title/title.html.twig', {'p': {'As': ui_i(3), 'Size': 'base', 'Weight': 'bold'}, 'children': c_1}, with_context = false) }}
          {%- set c_2 -%}
            {{ ui_text(ui_tpl(v_countLabel, [ui_len(ui_where(v_cards, 'lane', ui_get(v_lane, ['key'])))])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_2}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/group/group.html.twig', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'between'}, 'children': c_3}, with_context = false) }}
        {%- set c_9 -%}
          {%- for v_c in ui_l(ui_where(v_cards, 'lane', ui_get(v_lane, ['key']))) %}
            {%- set c_8 -%}
              {%- set c_4 -%}
                {{ ui_text(ui_get(v_c, ['title'])) }}
              {%- endset -%}
              {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_4}, with_context = false) }}
              {%- if ui_t(ui_eq(v_card, 'detail')) %}
                {%- set c_7 -%}
                  {%- set c_5 -%}
                    {{ ui_text(ui_get(v_c, ['tag'])) }}
                  {%- endset -%}
                  {{ include('blocks/pill.html.twig', {'p': {'tone': 'blue', 'icon': 'tag'}, 'children': c_5}, with_context = false) }}
                  {%- set c_6 -%}
                    {{ ui_text(ui_get(v_c, ['who'])) }}
                  {%- endset -%}
                  {{ include('ui/text/text.html.twig', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_6}, with_context = false) }}
                {%- endset -%}
                {{ include('ui/group/group.html.twig', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'between', 'Class': 'flex-wrap'}, 'children': c_7}, with_context = false) }}
              {%- endif %}
            {%- endset -%}
            {{ include('ui/list/list-item.html.twig', {'p': {'Class': ui_s(ui_cnv(['flex flex-col rounded bg-card inset-ring inset-ring-border', (ui_t(ui_eq(v_density, 'compact')) ? 'gap-2 p-2' : 'gap-2 p-4')])), 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_8}, with_context = false) }}
          {%- endfor %}
        {%- endset -%}
        {{ include('ui/list/list.html.twig', {'p': {'Class': 'm-0 flex list-none flex-col gap-2 p-0'}, 'children': c_9}, with_context = false) }}
      {%- endset -%}
      {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '4', 'Align': 'stretch', 'Class': 'rounded bg-muted p-4', 'Attrs': ui_attrs(['data-testid', 'lane'])}, 'children': c_10}, with_context = false) }}
    {%- endfor %}
  {%- endset -%}
  {{ include('ui/grid/grid.html.twig', {'p': {'Cols': ui_s((ui_t(ui_eq(v_cols, '2')) ? '1-2' : '1-3')), 'Class': 'items-start gap-4', 'Attrs': ui_attrs(['data-testid', 'lanes'])}, 'children': c_11}, with_context = false) }}
{%- endset -%}
{{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}, 'children': c_12}, with_context = false) }}
